        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'INTRODUCTION-ARTIFICIAL-INTELLIGENCE-BASIC-V1'],
            [
                'module_no' => 19,
                'title' => 'Introduction to Artificial Intelligence',
                'year_level' => 'Year 4',
                'version_no' => 1,
                'version_name' => 'Introduction to Artificial Intelligence Fundamentals',
                'version_code' => 'V1',
                'description' => 'Search algorithms, knowledge representation, planning, natural language processing, and the AI landscape. This version emphasizes concept foundations, guided examples, careful interpretation, and beginner assessment readiness.',
                'estimated_minutes' => 650,
                'sort_order' => 55,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'INTRODUCTION-ARTIFICIAL-INTELLIGENCE-BASIC-V1')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'INTRODUCTION-ARTIFICIAL-INTELLIGENCE-BASIC-V1')
            ->update([
                'mcq_questions' => json_encode($this->mcqQuestions(), JSON_UNESCAPED_UNICODE),
